#!/bin/sh
# amalgamation.sh : generate a single-file amalgamation of kiln
# Usage: sh bin/amalgamation.sh > kiln-amalgamation.c
#
# The output file compiles with: cc -O2 -o kiln kiln-amalgamation.c
set -e

cd "$(dirname "$0")/.."

# Recursively expand #include "..." (local includes only).
# System includes (#include <...>) are passed through.
expand() {
    local file="$1"
    local dir
    dir=$(dirname "$file")

    while IFS= read -r line; do
        case "$line" in
        '#include "'*)
            # Extract the path from #include "path"
            inc=$(printf '%s' "$line" | sed 's/^#include "\(.*\)"/\1/')
            # Resolve relative to the including file's directory
            if [ -f "$dir/$inc" ]; then
                target="$dir/$inc"
            elif [ -f "$inc" ]; then
                target="$inc"
            else
                # Can't resolve - pass through as-is
                printf '%s\n' "$line"
                continue
            fi
            printf '/* --- begin %s --- */\n' "$inc"
            expand "$target"
            printf '/* --- end %s --- */\n' "$inc"
            ;;
        *)
            printf '%s\n' "$line"
            ;;
        esac
    done < "$file"
}

cat << 'HEADER'
/* kiln-amalgamation.c : kiln build system - amalgamation (single-file) build
 *
 * This file is auto-generated by bin/amalgamation.sh. Do not edit directly.
 * Compile with: cc -O2 -o kiln kiln-amalgamation.c
 *
 * Copyright (c) 2025-2026 Jon Mayo <jon@rm-f.net>
 * Licensed under MIT OR Apache-2.0 */
HEADER

expand bootstrap.c
